        </article>
      </div>
    </section>
  </main>
</template>
<script>
import ImgUpload from '@/components/ImgUpload'
import { clientAiMatch } from '@/api/client-user'
export default { name: 'ClientImageMatch', components: { ImgUpload }, data() { return { direction: 'lost', images: '', description: '', loading: false, searched: false, results: [], recordId: null, brokenImages: {} } }, computed: { uploadedCount() { return (this.images || '').split(',').filter(Boolean).length } }, methods: { async match() { const imageUrls = (this.images || '').split(',').filter(Boolean); if (!imageUrls.length) return this.$message.warning('请至少上传一张物品图片'); this.loading = true; this.searched = false; try { const res = await clientAiMatch({ direction: this.direction, imageUrls, description: this.description }); this.recordId = res.data && res.data.recordId; this.results = ((res.data && res.data.results) || []).slice(0, 4); this.searched = true; this.$nextTick(() => document.querySelector('.results-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' })) } finally { this.loading = false } }, hasImage(item) { return Boolean(item.coverImage) && !this.brokenImages[item.businessId] }, imageError(id) { this.$set(this.brokenImages, id, true) }, percent(v) { return `${Math.round(Number(v || 0) * 100)}%` }, date(v) { return v ? String(v).slice(0, 10) : '时间待补充' }, goDetail(item) { this.$router.push(`/user/detail/${item.businessId}`) } } }
</script>
